member.example:
This example demonstrates how to configure the Languages property:

<SfRichTextEditor>
    <RichTextEditorCodeBlockSettings Languages="@customLanguages" />
</SfRichTextEditor>
@code {
    private List<CodeBlockLanguageModel> customLanguages = new List<CodeBlockLanguageModel>
    {
        new CodeBlockLanguageModel { Label = "C#", Language = "csharp" },
        new CodeBlockLanguageModel { Label = "JavaScript", Language = "javascript" },
        new CodeBlockLanguageModel { Label = "Python", Language = "python" }
    };
}

In the following example, insert the horizontal line using the custom tool option.

@using Syncfusion.Blazor.RichTextEditor;
<SfRichTextEditor @ref="RTEInstance">
    <RichTextEditorToolbarSettings Items="@Tools">
        <RichTextEditorCustomToolbarItems>
            <RichTextEditorCustomToolbarItem Name="Symbol">
                 <Template>
                    <button class="e-btn e-tbar-btn" @onclick="ClickHandler">
                         <div class="e-tbar-btn-text" style="font-weight: 500;">__</div>
                    </button>
                 </Template>
            </RichTextEditorCustomToolbarItem>
        </RichTextEditorCustomToolbarItems>
    </RichTextEditorToolbarSettings>
</SfRichTextEditor>
@code {
    SfRichTextEditor RTEInstance;
    private List<ToolbarItemModel> Tools = new List<ToolbarItemModel>()
    {
        new ToolbarItemModel() { Name = "Symbol", TooltipText = "Insert horizontal line" }
    };
    private async Task ClickHandler() {
        await this.RTEInstance.ExecuteCommandAsync(CommandName.InsertHTML, "<hr>");
    };
}

