@using Syncfusion.Blazor.RichTextEditor; 
<SfRichTextEditor @ref="RichTextEditorObj"> 
    <RichTextEditorEvents SlashMenuItemSelecting="OnSlashMenuItemSelect" /> 
    <RichTextEditorSlashMenuSettings Enable = "true" Items="@slashmenu" PopupHeight="300px" PopupWidth="320px" /> 
</SfRichTextEditor> 
@code { 
    private SfRichTextEditor RichTextEditorObj; 
    public string meetingNotes = @"<p><strong>Meeting Notes</strong></p><table class=""e-rte-table"" style=""width: 100%; min-width: 0px; height: 150px;""> <tbody> <tr style=""height: 20%;""> <td style=""width: 50%;""><strong>Attendees</strong></td> <td style=""width: 50%;""><br></td> </tr> <tr style=""height: 20%;""> <td style=""width: 50%;""><strong>Date &amp; Time</strong></td> <td style=""width: 50%;""><br></td> </tr> <tr style=""height: 20%;""> <td style=""width: 50%;""><strong>Agenda</strong></td> <td style=""width: 50%;""><br></td> </tr> <tr style=""height: 20%;""> <td style=""width: 50%;""><strong>Discussed Items</strong></td> <td style=""width: 50%;""><br></td> </tr> <tr style=""height: 20%;""> <td style=""width: 50%;""><strong>Action Items</strong></td> <td style=""width: 50%;""><br></td> </tr> </tbody> </table>"; 
    private List<SlashMenuItemModel> Tools = new List<SlashMenuItemModel> 
    { 
        new SlashMenuItemModel { Command = SlashMenuCommand.Paragraph }, 
        new SlashMenuItemModel { Command = SlashMenuCommand.Heading1 }, 
        new SlashMenuItemModel() { Text="Meeting Notes", Type= "Custom" , IconCss = "e-icons e-description", Description= "Insert a meeting note template." } 
    }; 
    public void OnSlashMenuItemSelect( MentionValueSelectingEventArgs<SlashMenuItemModel> args) { 
        await RichTextEditorObj.ExecuteCommandAsync(CommandName.InsertHTML, meetingNotes); 
    } 
}

member.code:

void OnSlashMenuItemSelecting(SlashMenuSelectEventArgs<SlashMenuItemModel> args) 
{ 
    if (!IsSelectionAllowed(args.ItemData)) 
    { 
        args.Cancel = true; // Cancels the selection if conditions are not met 
    } 
}

