member.example:

@using Syncfusion.Blazor.RichTextEditor
<SfRichTextEditor @ref="rteObj">
</SfRichTextEditor>
<button @onclick="btnClick">Insert Code Block</button>
@code {
    private SfRichTextEditor rteObj;

    private async Task btnClick()
    {
        await rteObj.ExecuteCommandAsync(
            CommandName.InsertCodeBlock,
            new CodeBlockCommandArgs { Language = "typescript", Label = "TypeScript" },
            new ExecuteCommandOption { Undo = true }
        );
    }
}

example.code:
var options = new FormatPainterParams
{
Action = FormatPainterAction.CopyFormat,
Options = new FormatPainterOptions
{
AllowedFormats = "b; em; strong",
DeniedFormats = "img; a",
}
};
await RichTextEditor.ExecuteCommandAsync(CommandName.CopyFormatPainter, options);

options.Action = FormatPainterAction.PasteFormat;
await RichTextEditor.ExecuteCommandAsync(CommandName.ApplyFormatPainter, options);

options.Action = FormatPainterAction.Escape;
await RichTextEditor.ExecuteCommandAsync(CommandName.CopyFormatPainter, options);
